{
  "name": "ThreeLevelLifts",
  "description": "Two lifts carry five boxes up three levels; an emergency stop and interlocks keep every move safe to start.",
  "version": "1.0.0",
  "variables": {
    "local": [
      {
        "name": "Active",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The line runs"
      },
      {
        "name": "Stopped",
        "type": "BOOL",
        "initialValue": false,
        "comment": "The emergency stop was pressed and the line has not been started again"
      },
      {
        "name": "StepA",
        "type": "INT",
        "initialValue": 0,
        "comment": "Lift A: 0 load at level 1, 1 settle, 2 rise, 3 unload at level 2, 4 lower"
      },
      {
        "name": "StepB",
        "type": "INT",
        "initialValue": 0,
        "comment": "Lift B: the same sequence, one level higher"
      },
      {
        "name": "SettleA",
        "type": "TON",
        "comment": "Lift A: the box is still before the lift rises"
      },
      {
        "name": "UnloadA",
        "type": "TON",
        "comment": "Lift A: time for the box to leave at the top"
      },
      {
        "name": "SettleB",
        "type": "TON",
        "comment": "Lift B: the box is still before the lift rises"
      },
      {
        "name": "UnloadB",
        "type": "TON",
        "comment": "Lift B: time for the box to leave at the top"
      },
      {
        "name": "Boxes",
        "type": "CTU",
        "comment": "Counts the boxes that reached the top"
      }
    ],
    "inputs": [
      {
        "name": "Start",
        "type": "BOOL",
        "address": "%IX0.0",
        "comment": "StartButton.pressed: start the line"
      },
      {
        "name": "EStopOk",
        "type": "BOOL",
        "address": "%IX0.1",
        "comment": "EStop1.ok: TRUE while the emergency stop is released"
      },
      {
        "name": "BoxOnA",
        "type": "BOOL",
        "address": "%IX0.2",
        "comment": "EyeFoot.detect: a box has reached the middle of lift A at level 1"
      },
      {
        "name": "BoxOnB",
        "type": "BOOL",
        "address": "%IX0.3",
        "comment": "EyeMid.detect: a box has reached the middle of lift B at its bottom level"
      },
      {
        "name": "BoxAtTop",
        "type": "BOOL",
        "address": "%IX0.4",
        "comment": "EyeTop.detect: a box is on the outfeed belt at level 3"
      },
      {
        "name": "AAtLow",
        "type": "BOOL",
        "address": "%IX0.5",
        "comment": "LiftA.atLevel1: lift A rests at level 1"
      },
      {
        "name": "AAtHigh",
        "type": "BOOL",
        "address": "%IX0.6",
        "comment": "LiftA.atLevel2: lift A rests at level 2"
      },
      {
        "name": "BAtLow",
        "type": "BOOL",
        "address": "%IX0.7",
        "comment": "LiftB.atLevel1: lift B rests at its bottom level (level 2 of the plant)"
      },
      {
        "name": "BAtHigh",
        "type": "BOOL",
        "address": "%IX1.0",
        "comment": "LiftB.atLevel2: lift B rests at its top level (level 3 of the plant)"
      }
    ],
    "outputs": [
      {
        "name": "RunInfeed",
        "type": "BOOL",
        "address": "%QX0.0",
        "comment": "Infeed.run: run the belt that feeds lift A"
      },
      {
        "name": "RunTransfer",
        "type": "BOOL",
        "address": "%QX0.1",
        "comment": "Transfer.run: run the belt between the lifts, level 2"
      },
      {
        "name": "RunOutfeed",
        "type": "BOOL",
        "address": "%QX0.2",
        "comment": "Outfeed.run: run the belt to the bin, level 3"
      },
      {
        "name": "AUp",
        "type": "BOOL",
        "address": "%QX0.3",
        "comment": "LiftA.up: raise lift A"
      },
      {
        "name": "ADown",
        "type": "BOOL",
        "address": "%QX0.4",
        "comment": "LiftA.down: lower lift A"
      },
      {
        "name": "ARun",
        "type": "BOOL",
        "address": "%QX0.5",
        "comment": "LiftA.run: run the surface of lift A"
      },
      {
        "name": "BUp",
        "type": "BOOL",
        "address": "%QX0.6",
        "comment": "LiftB.up: raise lift B"
      },
      {
        "name": "BDown",
        "type": "BOOL",
        "address": "%QX0.7",
        "comment": "LiftB.down: lower lift B"
      },
      {
        "name": "BRun",
        "type": "BOOL",
        "address": "%QX1.0",
